mapper.update:
UPDATE products.products
SET name      = #{name},
    stock     = #{stock},
    version   = version + 1,
    update_at = #{updateAt}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = false

UPDATE products.products
SET deleted   = true,
    update_at = #{now}
WHERE id = #{id}
  AND deleted = false

UPDATE products.products
SET deleted   = true,
    update_at = #{now}
WHERE deleted = false
  AND id IN
#{id}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM products.products WHERE id = #{id} AND deleted = false
)
